from pathlib import Path
import json,hashlib,re,os
c=Path('.cache/p03r3')
def pin(p):
 p=Path(p);d=p.read_bytes();return {'path':str(p),'bytes':len(d),'sha256':hashlib.sha256(d).hexdigest()}
def pair(prefix,expected):
 before=json.loads((c/(prefix+'before.json')).read_text());after=json.loads((c/(prefix+'after.json')).read_text());assert before==after
 v=json.loads((c/(prefix+'execution.json')).read_text());assert v['inputsUnchanged'] and len(v['runs'])==2
 for r in v['runs']:
  assert r['exitCode']==0
  f=c/r['log'];s=f.read_text();summary={k:int(re.search(r'^# '+k+r' (\d+)$',s,re.M)[1]) for k in ['tests','pass','fail','cancelled','skipped']}
  assert summary=={'tests':expected,'pass':expected,'fail':0,'cancelled':0,'skipped':0}
  r.update(summary=summary,reportedMs=float(re.search(r'^# duration_ms ([\d.]+)$',s,re.M)[1]),logPin=pin(f))
 return {'inputCount':len(before),'before':pin(c/(prefix+'before.json')),'after':pin(c/(prefix+'after.json')),'runs':v['runs']}
old=pair('whole-',157);new=pair('foreground-whole-',87);difficulty=pair('difficulty-whole-',10)
hold=json.loads((c/'source-held-03.json').read_text())
for r in hold['sourceFiles']:
 actual=pin(r['path']);assert all(actual[k]==r[k] for k in ['bytes','sha256'])
previous=json.loads((c/'foreground-whole-after.json').read_text());current=json.loads((c/'difficulty-whole-after.json').read_text())
assert [a['path'] for a,b in zip(previous,current) if a!=b]==['game/test/difficulty-host.test.mjs']
assert [a['path'] for a in previous]==[a['path'] for a in current]
for r in current:
 a=pin(r['path']);assert all(a[k]==r[k] for k in ['bytes','sha256'])
evidence=[pin(p) for p in sorted(c.iterdir()) if p.is_file() and p.name not in ['verification.json','seal.py']]
free=os.statvfs('.').f_bavail*os.statvfs('.').f_frsize;assert free>=268435456
record={'format':'revealline-local-source-verification.v1','base':hold['base'],'scope':'P03-R3 internal source candidate. Navigation-only Library launch adapters; native/physical/integration/public acceptance pending. No commit or version claim.','sourceFiles':hold['sourceFiles'],'held':pin(c/'source-held-03.json'),'finalAffectedPair':new,'difficultyCompatibilityPair':difficulty,'priorEightFilePair':old,'countBoundary':'157 each runtime is the predecessor before foreground retirement.87 each runtime is the four affected complete files on final foreground source; counts are not additive or a final full-suite total. App/index unchanged across foreground successor. The separate10/10 difficulty file uses the final test-only visible-action adaptation; runtime is identical to held02 and this does not imply a combined phase total.','sourceReview':'Root read original app/Library delta and requested foreground retirement. Parfit read final foreground panel0ff and closed no blocker; no duplicate test or native claim. Root owns actual native observation on pinned preview. Final test-only adaptation peer separately requested.','static':'Final original five owned paths and the separate difficulty-host test pass ESLint where applicable, Prettier check and git diff --check; final panel syntax checked on20/22. No full build or six-gate run.','failures':['Initial test fixture briefs count and ISO timestamp rejected before app entry. Original logs/source snapshots retained.','Finite host fixture initially opened a completed overview instead of explicitly selecting a mission; canvas drawImage adapter was absent; same saved flight re-verification legitimately changed savedAt. Corrected actual controls/models, no product fix inferred from these failures.','Actual export/restore test initially read the serialized storage envelope as a raw library. Corrected to public loadLibrary adapter; both native-operation host paths then pass.','Root source review identified launch intent surviving foreground loss. Original blur/hidden tests reproduce four source failures; two pagehide cases additionally lacked hidden-document modeling. Original0/6 and first-correction4/6 logs retained; corrected6/6 and final whole pair pass.','One tiny shell write was refused ENOSPC although fresh subsequent free-space check was above reserve; no source changed in refused command. No cleanup of other owned data.','Proposed extra fixture intake exceeded2MiB and asserted before any writes; exact existing11MB pack is shared through a checked read-only hardlink, not copied.'], 'testOnlyCompatibility':'Original difficulty helper used hidden Workshop Restart. One case reproduced that failure against exact4397 projection before adaptation. Actual visible Pause Restart now explicitly confirms; terminal Retry remains direct. Installed/challenge closes await the guarded handoff. The two-chapter case explicitly opens visible Expansion packs. All original difficulty/checkpoint/save expectations remain. Initial2/10 and first9/10 failures retained; final10/10 bothNodes.','preview':{'binding':pin(c/'preview/binding.json'),'sourceChecks':pin(c/'preview/source-checks.json'),'helper':pin(c/'preview/serve.py'),'scope':'Root-owned native work uses Git4397 plus two held02 immutable memory overlays. Six HTTP byte checks and Range206 passed; no native action by source author.'},'limits':['Synthetic completed picture fixture is source navigation coverage, never a native achievement.','Picture Replay preserves existing current-authored artwork preparation. Exact earned-original replay fidelity remains P08-A/P07; viewing/backups retain existing pins.','No browser actions by source author, media downloads, new original archive/assets, build, schema, producer, source version or publication actions.','Mode A2 and other branch composition require separate exact integrated qualification.'], 'capacity':{'freeBeforeSeal':free,'floorBytes':268435456,'cacheEvidenceBytes':sum(r['bytes'] for r in evidence),'extraInputs':pin(c/'additional-test-inputs.json')},'evidence':evidence}
(c/'verification.json').write_text(json.dumps(record,indent=2)+'\n');print(json.dumps(pin(c/'verification.json')))
